(527875, 52563, 5391, '<td valign="top">Beautiful macro.  The little glint on the drop really makes this stand out.  The background colors are also beautiful and add to the composition.  9</td>', 'Beautiful macro.  The little glint on the drop really makes this stand out.  The background colors are also beautiful and add to the composition.  9', '2004-01-01 00:42:27.000000', NULL, 1),
(527876, 52483, 327, '<td valign="top">The tones, light and focus here are stunning. I would of liked to see the officers head. However....it leaves the viewer wanting more. That''s a good thing. Really nice, photo journalistic.......Norman Rockwell. Congrats, great moment in time.</td>', 'The tones, light and focus here are stunning. I would of liked to see the officers head. However....it leaves the viewer wanting more. That''s a good thing. Really nice, photo journalistic.......Norman Rockwell. Congrats, great moment in time.', '2004-01-01 00:43:20.000000', NULL, 1),
(527877, 53089, 13440, '<td valign="top">Nice strong red with details here, nice work</td>', 'Nice strong red with details here, nice work', '2004-01-01 00:43:37.000000', NULL, 1),
(527878, 52276, 6870, '<td valign="top">Oh yeah. Nice and moody, peaceful and calm. Composition is right on. Lovely tones. Very  nice! 9</td>', 'Oh yeah. Nice and moody, peaceful and calm. Composition is right on. Lovely tones. Very  nice! 9', '2004-01-01 00:43:40.000000', NULL, 1),
