(528038, 52391, 12160, '<td valign="top">Beautiful composition, I love the noise introduced in this photo. The tilt at the bottom doesn''t really bother me. I would have preferred the subjects to be bigger and crop the top which no detail can be seen anyway.</td>', 'Beautiful composition, I love the noise introduced in this photo. The tilt at the bottom doesn''t really bother me. I would have preferred the subjects to be bigger and crop the top which no detail can be seen anyway.', '2004-01-01 02:47:20.000000', NULL, 1),
(528039, 50097, 14952, '<td valign="top">Nice shot.  The castle seems to be leening a bit which is a bit distracting.  I think a vertical shot of just the castle and the fireworks around it would be very nice</td>', 'Nice shot.  The castle seems to be leening a bit which is a bit distracting.  I think a vertical shot of just the castle and the fireworks around it would be very nice', '2004-01-01 02:47:21.000000', NULL, 1),
(528041, 52226, 11034, '<td valign="top">It is a shame that they don look the camera, but i like the shoot. Nice contrast and balance. Good luck.</td>', 'It is a shame that they don look the camera, but i like the shoot. Nice contrast and balance. Good luck.', '2004-01-01 02:47:41.000000', NULL, 1),
(528042, 51972, 14952, '<td valign="top">one of the best baby shots I have ever seen!</td>', 'one of the best baby shots I have ever seen!', '2004-01-01 02:47:46.000000', NULL, 1),
(528043, 52303, 8054, '<td valign="top">Good job with the water ripples. And I like how the seagull is still looking at the water like it''s interested in the ripples. Nice job!</td>', 'Good job with the water ripples. And I like how the seagull is still looking at the water like it''s interested in the ripples. Nice job!', '2004-01-01 02:48:41.000000', NULL, 1),
(528044, 52398, 14952, '<td valign="top">The few white areas in the dark foreground are a bit distraction, but other than that, it is a beautiful shot!</td>', 'The few white areas in the dark foreground are a bit distraction, but other than that, it is a beautiful shot!', '2004-01-01 02:48:47.000000', NULL, 1),
(528045, 53038, 12160, '<td valign="top">I''t always been a beautifl subject and this is not an exception. Composition in great, colors wonderful. However, too much of a cliche alreay.</td>', 'I''t always been a beautifl subject and this is not an exception. Composition in great, colors wonderful. However, too much of a cliche alreay.', '2004-01-01 02:49:56.000000', NULL, 1),
(528046, 53070, 11034, '<td valign="top">Nice contrast and blance. Good luck.</td>', 'Nice contrast and blance. Good luck.', '2004-01-01 02:50:05.000000', NULL, 1),
(528047, 49322, 14952, '<td valign="top">I like the framing of this shot.  The position of the lizard is perfect.  It seems a bit dark to me though</td>', 'I like the framing of this shot.  The position of the lizard is perfect.  It seems a bit dark to me though', '2004-01-01 02:50:08.000000', NULL, 1),
(528048, 53107, 12160, '<td valign="top">Awesome clarity, nice colors, quarter down the bottom is quite busy for me. shallow dof is great.</td>', 'Awesome clarity, nice colors, quarter down the bottom is quite busy for me. shallow dof is great.', '2004-01-01 02:51:29.000000', NULL, 1),
(528049, 52930, 14952, '<td valign="top">perfect shot, I don''t care for the white rounded edges, but other than that it is perfect!</td>', 'perfect shot, I don''t care for the white rounded edges, but other than that it is perfect!', '2004-01-01 02:52:45.000000', NULL, 1),
(528050, 52353, 13749, '<td valign="top">that white spot in the sky is a bit distracting.. otherwise, great composition and exposure control.</td>', 'that white spot in the sky is a bit distracting.. otherwise, great composition and exposure control.', '2004-01-01 02:52:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(528051, 52398, 8054, '<td valign="top">Amazing clouds and lighting! The only thing I would have done is clone out the three small lights in the black area. Otherwise awesome job!</td>', 'Amazing clouds and lighting! The only thing I would have done is clone out the three small lights in the black area. Otherwise awesome job!', '2004-01-01 02:53:08.000000', NULL, 1),
(528052, 51484, 6804, '<td valign="top">This is just beautiful! Such character. the color is great and not over done. I like the angle you selected here. The trees add to the shot without taking away from the main subject. 10+</td>', 'This is just beautiful! Such character. the color is great and not over done. I like the angle you selected here. The trees add to the shot without taking away from the main subject. 10+', '2004-01-01 02:53:39.000000', NULL, 1),
(528053, 53089, 12160, '<td valign="top">Beautiful rose, nice soft foculs, lighting is great. Great shot but nothing extraordinary that sets it apart from other rose photos.</td>', 'Beautiful rose, nice soft foculs, lighting is great. Great shot but nothing extraordinary that sets it apart from other rose photos.', '2004-01-01 02:53:41.000000', NULL, 1),
(528054, 50767, 8054, '<td valign="top">Great subject but I would have cropped the bottom a little closer.</td>', 'Great subject but I would have cropped the bottom a little closer.', '2004-01-01 02:54:02.000000', NULL, 1),
(528055, 52577, 14952, '<td valign="top">I don''t like the large white border, but other than that, WOW.  An incredible shot with the perfect titile</td>', 'I don''t like the large white border, but other than that, WOW.  An incredible shot with the perfect titile', '2004-01-01 02:54:38.000000', NULL, 1),
(528056, 53035, 8054, '<td valign="top">Great job with the macro shot and DOF. Nice textures, too!</td>', 'Great job with the macro shot and DOF. Nice textures, too!', '2004-01-01 02:54:49.000000', NULL, 1),
(528057, 53073, 6804, '<td valign="top">A fun shot! full of life. I like the angle and the color.</td>', 'A fun shot! full of life. I like the angle and the color.', '2004-01-01 02:56:00.000000', NULL, 1),
(528058, 52614, 12160, '<td valign="top">nice soft focus, great details.</td>', 'nice soft focus, great details.', '2004-01-01 02:56:55.000000', NULL, 1),
(528059, 52226, 14952, '<td valign="top">I love the idea for this shot.  I wish that the faces (especially the groom''s) weren''t so hidden.</td>', 'I love the idea for this shot.  I wish that the faces (especially the groom''s) weren''t so hidden.', '2004-01-01 02:57:08.000000', NULL, 1),
(528061, 52489, 8054, '<td valign="top">Great shot and composition.  The snow and DOF adds a nice touch.</td>', 'Great shot and composition.  The snow and DOF adds a nice touch.', '2004-01-01 02:57:25.000000', NULL, 1),
(528062, 53108, 14952, '<td valign="top">The guard rail is distracting to me. I think if you cropped it just a bit above that it would be perfect.  You captured the snow perfectly</td>', 'The guard rail is distracting to me. I think if you cropped it just a bit above that it would be perfect.  You captured the snow perfectly', '2004-01-01 02:58:08.000000', NULL, 1),
(528063, 52413, 8054, '<td valign="top">The dog is showing some serious emotion. He/she looks so sad and looks like he/she wants to get out. It looks great in b/w, too!</td>', 'The dog is showing some serious emotion. He/she looks so sad and looks like he/she wants to get out. It looks great in b/w, too!', '2004-01-01 02:58:52.000000', NULL, 1),
(528064, 53113, 12160, '<td valign="top">Love the clarify of focus, the shallow dof but it doesn''t communicate anything to me. Perspective is different as well.</td>', 'Love the clarify of focus, the shallow dof but it doesn''t communicate anything to me. Perspective is different as well.', '2004-01-01 02:59:34.000000', NULL, 1),
(528065, 51972, 11034, '<td valign="top">Nice baby. Congratulation for the shoot and for the baby. Good luck.</td>', 'Nice baby. Congratulation for the shoot and for the baby. Good luck.', '2004-01-01 02:59:38.000000', NULL, 1),
(528066, 52390, 6804, '<td valign="top">My hats off to you for getting out in this cold to shoot this so I can enjoy it from the warmth of my home. It has just the right amount of shutter here. This is beautiful in every way. 10+</td>', 'My hats off to you for getting out in this cold to shoot this so I can enjoy it from the warmth of my home. It has just the right amount of shutter here. This is beautiful in every way. 10+', '2004-01-01 02:59:50.000000', NULL, 1),
(528067, 53043, 14952, '<td valign="top">Great shot of the gator, but the hands and watch are a bit distracting to me</td>', 'Great shot of the gator, but the hands and watch are a bit distracting to me', '2004-01-01 03:01:12.000000', NULL, 1),
(528068, 50877, 6804, '<td valign="top">I love this kind of shot! The color is brilliant and the clarity is stunning. Great work here.</td>', 'I love this kind of shot! The color is brilliant and the clarity is stunning. Great work here.', '2004-01-01 03:01:39.000000', NULL, 1),
(528069, 52988, 10170, '<td valign="top">Trying to work out how you did this.  A bulb (globe?) without the glass and going up in smoke?  Really hope there is an explanation.  Quite fantastic, the lighting is absolutely sensational.</td>', 'Trying to work out how you did this.  A bulb (globe?) without the glass and going up in smoke?  Really hope there is an explanation.  Quite fantastic, the lighting is absolutely sensational.', '2004-01-01 03:01:47.000000', NULL, 1),
(528071, 50424, 14952, '<td valign="top">Very good shot.  I know from experience they can be very hard to capture.  The photo overall seems too red.  The bunny seems a bit red to me, but especially the snow.</td>', 'Very good shot.  I know from experience they can be very hard to capture.  The photo overall seems too red.  The bunny seems a bit red to me, but especially the snow.', '2004-01-01 03:02:45.000000', NULL, 1),
(528072, 52835, 8054, '<td valign="top">Great panoramic-style image! Not sure if the white spot in the upper left is supposed to be a star or the moon but it''s sort-of distracting especially with the mostly blue sky. Great job, however!</td>', 'Great panoramic-style image! Not sure if the white spot in the upper left is supposed to be a star or the moon but it''s sort-of distracting especially with the mostly blue sky. Great job, however!', '2004-01-01 03:04:39.000000', NULL, 1),
(528075, 50617, 8054, '<td valign="top">This is amazing! The spiral pattern created by the lights is awesome. I can see this one getting a ribbon for sure! 10</td>', 'This is amazing! The spiral pattern created by the lights is awesome. I can see this one getting a ribbon for sure! 10', '2004-01-01 03:06:53.000000', NULL, 1),
(528076, 53070, 8054, '<td valign="top">This has an amazing Ansel Adams feel to it (one of my favorite photographers). But the sky looks like it''s suffering from excess compression. I wanted to rate it higher, though.</td>', 'This has an amazing Ansel Adams feel to it (one of my favorite photographers). But the sky looks like it''s suffering from excess compression. I wanted to rate it higher, though.', '2004-01-01 03:09:41.000000', NULL, 1),
(528080, 52311, 12160, '<td valign="top">Love the symmetry, shallow dof works. Spanish-Grease?</td>', 'Love the symmetry, shallow dof works. Spanish-Grease?', '2004-01-01 03:11:47.000000', NULL, 1),
(528081, 52660, 8054, '<td valign="top">Excellent macro shot! Detail is amazing! 10</td>', 'Excellent macro shot! Detail is amazing! 10', '2004-01-01 03:11:57.000000', NULL, 1),
(528082, 52937, 12160, '<td valign="top">beaufiul composition, nice soft focus and lovely colors.</td>', 'beaufiul composition, nice soft focus and lovely colors.', '2004-01-01 03:12:35.000000', NULL, 1),
(528083, 53069, 8054, '<td valign="top">I think I would have cropped the bottom a bit closer but excellent image.</td>', 'I think I would have cropped the bottom a bit closer but excellent image.', '2004-01-01 03:12:45.000000', NULL, 1),
(528085, 52796, 13749, '<td valign="top">not sure the selective color adds much for me, unless there''s maybe a reason behind it.  the only thing i could think of is signs/signals, which could be nice.. but the restaurant signs appear to still be colorless.</td>', 'not sure the selective color adds much for me, unless there''s maybe a reason behind it.  the only thing i could think of is signs/signals, which could be nice.. but the restaurant signs appear to still be colorless.', '2004-01-01 03:13:39.000000', NULL, 1),
