(528088, 53032, 12160, '<td valign="top">I love the shaft of light coming through the dark clouds. Beautiful.</td>', 'I love the shaft of light coming through the dark clouds. Beautiful.', '2004-01-01 03:15:26.000000', NULL, 1),
(528089, 52311, 8054, '<td valign="top">This is the EXACT idea I had for a previous challenge! I have one minor problem with this image and it''s the edge of the table or whatnot at the end of the glasses. Otherwise one of the best images in this challenge!</td>', 'This is the EXACT idea I had for a previous challenge! I have one minor problem with this image and it''s the edge of the table or whatnot at the end of the glasses. Otherwise one of the best images in this challenge!', '2004-01-01 03:16:43.000000', NULL, 1),
(528090, 52895, 12160, '<td valign="top">Too busy for me. The photo is cluttered.</td>', 'Too busy for me. The photo is cluttered.', '2004-01-01 03:17:20.000000', NULL, 1),
(528091, 51482, 13749, '<td valign="top">the thicker tree that runs ''through'' the Christmas tree is a bit distracting - not sure if a different view was possible.</td>', 'the thicker tree that runs ''through'' the Christmas tree is a bit distracting - not sure if a different view was possible.', '2004-01-01 03:18:31.000000', NULL, 1),
(528092, 50844, 8054, '<td valign="top">Oh man, all these amazing images makes it hard to pick one favorite but this is one of them for sure. The Slight sepia tone lends well to the retro/antique feel of the image. 10!</td>', 'Oh man, all these amazing images makes it hard to pick one favorite but this is one of them for sure. The Slight sepia tone lends well to the retro/antique feel of the image. 10!', '2004-01-01 03:19:12.000000', NULL, 1),
