(528175, 52657, 6740, '<td valign="top">Great photo. Is it my eyes or are the trees leaning?  Bound to be in the top 10....</td>', 'Great photo. Is it my eyes or are the trees leaning?  Bound to be in the top 10....', '2004-01-01 08:19:19.000000', NULL, 1),
(528180, 52811, 6130, '<td valign="top">I like this.</td>', 'I like this.', '2004-01-01 08:25:56.000000', NULL, 1),
(528181, 49435, 12393, '<td valign="top">The theme is good and the picture is clear, the guy in uniform and the flag - the only suggestion going forward would be to try place the person so that the flag is not growing uut of his head. A less cluttered background may also make it a more powerful picture. I realize the above suggestions  may be impossible to do in some places ...but I those were the only things I could think of that could be improved.</td>', 'The theme is good and the picture is clear, the guy in uniform and the flag - the only suggestion going forward would be to try place the person so that the flag is not growing uut of his head. A less cluttered background may also make it a more powerful picture. I realize the above suggestions  may be impossible to do in some places ...but I those were the only things I could think of that could be improved.', '2004-01-01 08:27:29.000000', NULL, 1),
(528183, 52803, 6740, '<td valign="top">This is how all the lights look when I don''t have my glasses on........</td>', 'This is how all the lights look when I don''t have my glasses on........', '2004-01-01 08:33:37.000000', NULL, 1),
