(528644, 49898, 255, '<td valign="top">what a punkin angel! :)<br/> <br/>this is just beautiful jacko--the tones and contrasts are perfect, and he could not be any cuter! gorgeous shot from a very proud daddy! ;) 10.</td>', 'what a punkin angel! :) this is just beautiful jacko--the tones and contrasts are perfect, and he could not be any cuter! gorgeous shot from a very proud daddy! ;) 10.', '2004-01-01 14:45:27.000000', NULL, 1),
