(529527, 52909, 11897, '<td valign="top">Great shot, I would like to see the tree more to the side, just my opinion.</td>', 'Great shot, I would like to see the tree more to the side, just my opinion.', '2004-01-02 11:53:36.000000', NULL, 1),
