(530232, 52377, 9906, '<td valign="top">Beautiful sense of perspective!  I also love the nearly monochromatic feeling you can get with these kinds of lighter snow scenes!<br/>TC</td>', 'Beautiful sense of perspective!  I also love the nearly monochromatic feeling you can get with these kinds of lighter snow scenes!TC', '2004-01-03 00:43:22.000000', NULL, 1),
(530233, 52998, 5044, '<td valign="top">Wow! Fabulous colours. Amazing clarity.</td>', 'Wow! Fabulous colours. Amazing clarity.', '2004-01-03 00:43:28.000000', NULL, 1),
(530234, 52998, 13136, '<td valign="top">I love how the fish on top is looking at the camera. I''m not sure the DOF should have been so narrow, maybe a bit more wide. Great lighting and color.</td>', 'I love how the fish on top is looking at the camera. I''m not sure the DOF should have been so narrow, maybe a bit more wide. Great lighting and color.', '2004-01-03 00:43:29.000000', NULL, 1),
(530235, 52227, 9906, '<td valign="top">Very nice lighting!  A touch overexposed on the orange, but not bad.  Is the background real or a print?<br/>TC</td>', 'Very nice lighting!  A touch overexposed on the orange, but not bad.  Is the background real or a print?TC', '2004-01-03 00:44:54.000000', NULL, 1),
(530237, 51560, 13136, '<td valign="top">That is some intense green. It looks like the contrast got tweeked a bit too far on the design around the hole when you had to shrink the file size. It almost makes me dizzy.</td>', 'That is some intense green. It looks like the contrast got tweeked a bit too far on the design around the hole when you had to shrink the file size. It almost makes me dizzy.', '2004-01-03 00:46:43.000000', NULL, 1),
