INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(530240, 51406, 9906, '<td valign="top">I normally don\''t like the small photos here and will comment appropriately, but you\''ve used the small size very well here and have captured just enough of the subject.<br/>TC</td>', 'I normally don\''t like the small photos here and will comment appropriately, but you\''ve used the small size very well here and have captured just enough of the subject.TC', '2004-01-03 00:48:13.000000', NULL, 1),
(530252, 51421, 13136, '<td valign="top">Pretty shot. Great that the clouds were on the mountain instead of over. Good contrast in the foreground snow.</td>', 'Pretty shot. Great that the clouds were on the mountain instead of over. Good contrast in the foreground snow.', '2004-01-03 01:18:03.000000', NULL, 1),
(530267, 52411, 11073, '<td valign="top">nice soft feel.  My only comment is the tree on the right.  I think that I''d like to either see it more in the frame or not at all.  Just a thought.  Nice work.</td>', 'nice soft feel.  My only comment is the tree on the right.  I think that I''d like to either see it more in the frame or not at all.  Just a thought.  Nice work.', '2004-01-03 01:58:03.000000', NULL, 1),
(530269, 52985, 11073, '<td valign="top">Very sharp.  Colors and composition are pleasing.  Nice work.</td>', 'Very sharp.  Colors and composition are pleasing.  Nice work.', '2004-01-03 02:01:19.000000', NULL, 1),
(530272, 52793, 11073, '<td valign="top">Great "feel" to this picture.  Brings back some memories.  Nice work.</td>', 'Great "feel" to this picture.  Brings back some memories.  Nice work.', '2004-01-03 02:02:14.000000', NULL, 1),
(530273, 52707, 11073, '<td valign="top">wow, that''s awesome (the cats and your timing).  Very clear and sharp.  Hope very much that you put this story in your comments.  Nice work.</td>', 'wow, that''s awesome (the cats and your timing).  Very clear and sharp.  Hope very much that you put this story in your comments.  Nice work.', '2004-01-03 02:07:28.000000', NULL, 1),
