(531416, 53011, 14614, '<td valign="top">Interesting composition - glad the person''s in the shot.  One of my top picks.</td>', 'Interesting composition - glad the person''s in the shot.  One of my top picks.', '2004-01-04 14:47:57.000000', NULL, 1),
(531418, 53104, 14614, '<td valign="top">Interesting lighting - great colors.  One of my top picks.</td>', 'Interesting lighting - great colors.  One of my top picks.', '2004-01-04 14:48:57.000000', NULL, 1),
