(537108, 50097, 8682, '<td valign="top">Wow... it´s just a fantastic and beatiful picture. I like the colours.</td>', 'Wow... it´s just a fantastic and beatiful picture. I like the colours.', '2004-01-09 06:13:54.000000', NULL, 1),
(537109, 53040, 8682, '<td valign="top">Beatiful image.</td>', 'Beatiful image.', '2004-01-09 06:16:03.000000', NULL, 1),
