(537114, 52662, 8682, '<td valign="top">Wow... wow... what a fantastic picture! One of my favs of this challenge. It´s awesome. 10<br/></td>', 'Wow... wow... what a fantastic picture! One of my favs of this challenge. It´s awesome. 10', '2004-01-09 06:32:17.000000', NULL, 1),
