(537371, 52707, 15152, '<td valign="top">AMAZING! I can''t wait to hear the details of how this shot was taken.</td>', 'AMAZING! I can''t wait to hear the details of how this shot was taken.', '2004-01-09 12:44:59.000000', NULL, 1),
(537373, 52988, 5158, '<td valign="top">That''s just a great idea! Does the bulb wire produce the wonderfull smoke by itself or did you add some smoking stuff onto it?<br/>And yes, I do see the hand and finger too, so the title fits very well. Good luck</td>', 'That''s just a great idea! Does the bulb wire produce the wonderfull smoke by itself or did you add some smoking stuff onto it?And yes, I do see the hand and finger too, so the title fits very well. Good luck', '2004-01-09 12:45:54.000000', NULL, 1),
(537375, 53066, 15152, '<td valign="top">How did you get the skin tones so smooth? Almost looks photoshoped</td>', 'How did you get the skin tones so smooth? Almost looks photoshoped', '2004-01-09 12:47:21.000000', NULL, 1),
(537384, 52563, 5158, '<td valign="top">Wonderfull clarity and colorful background. Like the cropping too.<br/>The star reflection is just so well set and not too strong that it increases the briliance of the image while not taking overhand.<br/>Good luck!</td>', 'Wonderfull clarity and colorful background. Like the cropping too.The star reflection is just so well set and not too strong that it increases the briliance of the image while not taking overhand.Good luck!', '2004-01-09 12:53:19.000000', NULL, 1),
(537389, 52226, 5158, '<td valign="top">Wonderful use of selective desaturation: works great here. Also the angle of view is well choosen and cropping is also good. Good luck!</td>', 'Wonderful use of selective desaturation: works great here. Also the angle of view is well choosen and cropping is also good. Good luck!', '2004-01-09 12:55:39.000000', NULL, 1),
