(538557, 52413, 15992, '<td valign="top">Its great!</td>', 'Its great!', '2004-01-11 02:18:12.000000', NULL, 1),
(538695, 52707, 14603, '<td valign="top">Great action shot with super clarity. A bit worried (for you)about how you managed to get this shot..with no obvious protection...........a moat and telescopic lens ?</td>', 'Great action shot with super clarity. A bit worried (for you)about how you managed to get this shot..with no obvious protection...........a moat and telescopic lens ?', '2004-01-11 08:15:18.000000', NULL, 1),
