(538704, 52985, 14603, '<td valign="top">Well thought out composition and great sky giving the picture a gentle, peaceful quality.<br/>Hope you weren`t standing on the ice !! ...8</td>', 'Well thought out composition and great sky giving the picture a gentle, peaceful quality.Hope you weren`t standing on the ice !! ...8', '2004-01-11 08:22:24.000000', NULL, 1),
(538705, 53040, 14603, '<td valign="top">Really good action shot well captured.<br/>Well composed and good colour contrast between the lighthouse &amp; sky.<br/>If the picture had been a little bit sharper this would have been a 10</td>', 'Really good action shot well captured.Well composed and good colour contrast between the lighthouse & sky.If the picture had been a little bit sharper this would have been a 10', '2004-01-11 08:27:34.000000', NULL, 1),
(538707, 52067, 14603, '<td valign="top">Simple but very effective.</td>', 'Simple but very effective.', '2004-01-11 08:28:48.000000', NULL, 1),
