(540524, 51671, 5822, '<td valign="top">I like the harsh and directional lighting on the cat, especially the effect it has on the eyes. The shadow even gives the cat a tail !  Background is not evenly lit and it appears that someone''s shadow is visible.</td>', 'I like the harsh and directional lighting on the cat, especially the effect it has on the eyes. The shadow even gives the cat a tail !  Background is not evenly lit and it appears that someone''s shadow is visible.', '2004-01-12 23:04:21.000000', NULL, 1),
(540536, 52353, 5007, '<td valign="top">I think you did a very nice job of composition and lighting is perfect.</td>', 'I think you did a very nice job of composition and lighting is perfect.', '2004-01-12 23:22:15.000000', NULL, 1),
