(540563, 53071, 5822, '<td valign="top">Very clear and crisp shot with beautiful colors!  Composition is good too. Only the yellow of the rink may be a bit too saturated and overexposed but that''s a nit.  I like this photo alot. Well done.</td>', 'Very clear and crisp shot with beautiful colors!  Composition is good too. Only the yellow of the rink may be a bit too saturated and overexposed but that''s a nit.  I like this photo alot. Well done.', '2004-01-12 23:35:54.000000', NULL, 1),
(540566, 53035, 12160, '<td valign="top">Simply beautiful. Love the shallow dof. and the tone used.8</td>', 'Simply beautiful. Love the shallow dof. and the tone used.8', '2004-01-12 23:39:54.000000', NULL, 1),
(540567, 52413, 6804, '<td valign="top">This is an award winning shot. The subject is simple and to the point. The color is phenomenal; youve managed to accentuate the wood grain without distracting from your subject. Incredible detail throughout right down to the vignette border. 10<br/>This belongs in a gallery!<br/></td>', 'This is an award winning shot. The subject is simple and to the point. The color is phenomenal; youve managed to accentuate the wood grain without distracting from your subject. Incredible detail throughout right down to the vignette border. 10This belongs in a gallery!', '2004-01-12 23:40:47.000000', NULL, 1),
(540568, 52822, 12160, '<td valign="top">This photo tells a lot of stories. Great expressions on the faces of the kids.</td>', 'This photo tells a lot of stories. Great expressions on the faces of the kids.', '2004-01-12 23:42:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(540569, 52483, 6804, '<td valign="top">Beautiful work. The lighting here is incredible. This gets high marks from me all the way around. Technically perfect, very artistic and it tells a story. 10</td>', 'Beautiful work. The lighting here is incredible. This gets high marks from me all the way around. Technically perfect, very artistic and it tells a story. 10', '2004-01-12 23:48:50.000000', NULL, 1),
(540570, 52850, 6804, '<td valign="top">Incredible work! <br/>This is certainly the way to capture a child. This pulls emotion even from a total stranger. 10<br/></td>', 'Incredible work! This is certainly the way to capture a child. This pulls emotion even from a total stranger. 10', '2004-01-12 23:57:23.000000', NULL, 1),
(540572, 52662, 5822, '<td valign="top">SUPERB !!! How did you do this, with a yellow filter?  You''ve united the provincial and universal here. The colors give it a surreal  and eerie feel. Exceptionally well done.</td>', 'SUPERB !!! How did you do this, with a yellow filter?  You''ve united the provincial and universal here. The colors give it a surreal  and eerie feel. Exceptionally well done.', '2004-01-13 00:01:37.000000', NULL, 1),
