(540578, 51646, 5822, '<td valign="top">Cool effect with the brick in the chrome. Nice contrast and tones as well.</td>', 'Cool effect with the brick in the chrome. Nice contrast and tones as well.', '2004-01-13 00:18:38.000000', NULL, 1),
